import AppKit

extension NSPasteboard.PasteboardType {
    static let transientContent = Self("org.nspasteboard.TransientType")
}

public struct PasteboardSnapshot: Sendable {
    public struct Unrestorable: Error {}

    public static let maxTypeBytes = 8 * 1024 * 1024
    public static let maxTotalBytes = 16 * 1024 * 1024

    private static let unsupportedTypes = Set([
        NSPasteboard.PasteboardType.transientContent.rawValue,
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.AutoGeneratedType",
        "com.apple.pasteboard.promised-file-url"
    ] + NSFilePromiseReceiver.readableDraggedTypes)

    private typealias Representation = (type: NSPasteboard.PasteboardType, data: Data)
    private let items: [[Representation]]

    public init(_ board: NSPasteboard) throws {
        guard let originals = board.pasteboardItems else { throw Unrestorable() }
        let typesByItem = originals.map(\.types)
        // Inspect every item before requesting any data from the clipboard owner.
        guard typesByItem.allSatisfy({ types in
            !types.isEmpty && !types.contains { Self.unsupportedTypes.contains($0.rawValue) }
        }) else { throw Unrestorable() }

        var totalBytes = 0
        items = try zip(originals, typesByItem).map { item, types in
            try types.map { type in
                // AppKit exposes the byte count only after requesting the data.
                guard let data = item.data(forType: type),
                      data.count <= Self.maxTypeBytes,
                      data.count <= Self.maxTotalBytes - totalBytes else { throw Unrestorable() }
                totalBytes += data.count
                return (type, data)
            }
        }
    }

    @discardableResult public func restore(_ board: NSPasteboard, ifUnchangedSince generation: Int? = nil) -> Bool {
        let expected = generation ?? board.changeCount
        var restored: [NSPasteboardItem] = []
        for representations in items {
            let item = NSPasteboardItem()
            for (type, data) in representations {
                guard item.setData(data, forType: type) else { return false }
            }
            restored.append(item)
        }
        guard board.changeCount == expected else { return false }
        let cleared = board.clearContents()
        guard board.changeCount == cleared else { return false }
        return restored.isEmpty || board.writeObjects(restored)
    }
}
